function fine(k) {
  return esc(t(k)).replace("{p}", `<a href="#datenschutz">${esc(t("lk_priv"))}</a>`).replace("{a}", `<a href="#agb">${esc(t("lk_agb"))}</a>`);
}
const dtFmt = (d, o) => { try { return new Intl.DateTimeFormat(lang === "de" ? "de-DE" : "en-GB", Object.assign({ timeZone:"Europe/Berlin" }, o)).format(d); } catch (e) { return d.toISOString(); } };

/* ---------- Legal view ---------- */
const TITLE0 = document.title;
let legalKey = "impressum";
const WD = { open:false, n:"", m:"", r:"", d:"", x:"", done:null };
function legalSet() { return lang === "de" ? LEGAL_DE : LEGAL_EN; }
function renderLegal(k) {
  if (k) legalKey = k;
  const all = legalSet(), L = all[legalKey];
  const real = L.sec.filter(s => s[0][0] !== "@");
  const toc = real.length > 12 ? `<nav class="lg-toc" aria-label="${esc(t("lg_toc"))}"><b>${esc(t("lg_toc"))}</b><ol>${L.sec.map((s, i) => s[0][0] === "@" ? "" : `<li><button type="button" data-lgto="lgs${i}">${s[0]}</button></li>`).join("")}</ol></nav>` : "";
  const secs = L.sec.map((s, i) => s[0][0] === "@" ? `<p class="lg-part">${s[0].slice(1)}</p>` : `<section id="lgs${i}"><h2>${s[0]}</h2>${s[1]}</section>`).join("");
  $("legalBody").innerHTML = `<nav class="lg-nav" aria-label="${esc(t("lg_nav"))}">${LEGAL_KEYS.map(x => `<a href="#${x}"${x === legalKey ? ' aria-current="page"' : ""}>${esc(all[x].nav)}</a>`).join("")}</nav>
  <article class="lg-doc">
    <a class="lg-back" href="#top">${ic("left", 2)}<span>${esc(t("lg_back"))}</span></a>
    <h1>${esc(L.h)}</h1>
    <p class="lg-meta">${esc(t("lg_upd", { d:LEGAL_UPD[lang] }))}</p>
    ${L.intro ? `<p class="lg-intro">${esc(L.intro)}</p>` : ""}
    ${lang === "en" ? `<p class="lg-note">${esc(t("lg_en"))}</p>` : ""}
    <p class="lg-note tpl">${esc(t("lg_tpl"))}</p>
    ${legalKey === "widerruf" ? wdBox() : ""}${legalKey === "cookies" ? ccBox() : ""}
    ${toc}${secs}
  </article>`;
  const nv = $("legalBody").querySelector(".lg-nav"), cur = nv && nv.querySelector("[aria-current]");
  if (cur && nv.scrollWidth > nv.clientWidth) nv.scrollLeft = cur.offsetLeft - (nv.clientWidth - cur.offsetWidth) / 2;
  document.title = L.h + " | TipTop Service 24";
  if (legalKey === "widerruf") wdBind();
}
$("legalBody").addEventListener("click", e => {
  const to = e.target.closest("[data-lgto]");
  if (to) { const el = document.getElementById(to.dataset.lgto); if (el) { el.scrollIntoView({ behavior:reduce ? "auto" : "smooth", block:"start" }); el.setAttribute("tabindex", "-1"); el.focus({ preventScroll:true }); } return; }
  const w = e.target.closest("[data-wd]");
  if (w) {
    if (w.dataset.wd === "open") { WD.open = true; renderLegal(); const n = $("wdN"); if (n) n.focus(); }
    if (w.dataset.wd === "new") { WD.done = null; WD.open = true; renderLegal(); const n = $("wdN"); if (n) n.focus(); }
  }
});

/* Electronic withdrawal function (§ 356a BGB, in force since 19 June 2026):
   step 1 "Vertrag widerrufen" opens the form, step 2 "Widerruf bestätigen" sends it, then a receipt with date and time.
   Live site: POST /api/withdrawals, an automatic confirmation email, and the entry appears in the admin inbox. */
function wdBox() {
  if (WD.done) {
    const d = WD.done;
    return `<div class="wd done" id="wd" tabindex="-1"><span class="ck">${ic("check", 2.4)}</span><h2>${esc(t("wd_done_h"))}</h2>
      <p>${esc(t("wd_done_p", { d:dtFmt(d.at, { dateStyle:"long" }), t:dtFmt(d.at, { timeStyle:"short" }), m:d.m }))}</p>
      <dl class="wd-sum"><dt>${esc(t("wd_s_n"))}</dt><dd>${esc(d.n)}</dd><dt>${esc(t("wd_s_r"))}</dt><dd>${esc(d.r)}</dd>${d.d ? `<dt>${esc(t("wd_s_d"))}</dt><dd>${esc(d.d)}</dd>` : ""}${d.x ? `<dt>${esc(t("wd_s_x"))}</dt><dd>${esc(d.x)}</dd>` : ""}</dl>
      <p class="proto">${esc(t("proto"))}</p><button type="button" class="btn line" data-wd="new">${esc(t("wd_new"))}</button></div>`;
  }
  if (!WD.open) return `<div class="wd" id="wd"><h2>${esc(t("wd_h"))}</h2><p>${esc(t("wd_p"))}</p><button type="button" class="btn" data-wd="open">${esc(t("wd_go"))}</button></div>`;
  return `<form class="wd" id="wd" novalidate><h2>${esc(t("wd_h"))}</h2><p>${esc(t("wd_p"))}</p>
    <div class="two"><div><label class="lab-l" for="wdN">${esc(t("wd_name"))}</label><input class="inp" id="wdN" autocomplete="name" value="${esc(WD.n)}"></div>
    <div><label class="lab-l" for="wdM">${esc(t("wd_mail"))}</label><input class="inp" id="wdM" type="email" autocomplete="email" value="${esc(WD.m)}"></div></div>
    <div class="two"><div><label class="lab-l" for="wdR">${esc(t("wd_ref"))}</label><input class="inp" id="wdR" placeholder="${esc(t("wd_ref_ph"))}" value="${esc(WD.r)}"></div>
    <div><label class="lab-l" for="wdD">${esc(t("wd_dev"))}</label><input class="inp" id="wdD" placeholder="${esc(t("wd_dev_ph"))}" value="${esc(WD.d)}"></div></div>
    <div><label class="lab-l" for="wdX">${esc(t("wd_note"))}</label><textarea class="inp" id="wdX" rows="3">${esc(WD.x)}</textarea></div>
    <p class="err" id="wdErr" role="alert"></p><p class="fine">${esc(t("wd_hint"))}</p>
    <button type="submit" class="btn">${esc(t("wd_confirm"))}</button></form>`;
}
function wdBind() {
  const f = $("wd"); if (!f || f.tagName !== "FORM") return;
  const keep = () => { WD.n = $("wdN").value; WD.m = $("wdM").value; WD.r = $("wdR").value; WD.d = $("wdD").value; WD.x = $("wdX").value; };
  f.addEventListener("input", keep);
  f.addEventListener("submit", e => {
    e.preventDefault(); keep();
    const err = $("wdErr"), n = WD.n.trim(), m = WD.m.trim(), r = WD.r.trim();
    if (!n) { err.textContent = t("wd_err_name"); $("wdN").focus(); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(m)) { err.textContent = t("wd_err_mail"); $("wdM").focus(); return; }
    if (!r) { err.textContent = t("wd_err_ref"); $("wdR").focus(); return; }
    WD.done = { n, m, r, d:WD.d.trim(), x:WD.x.trim(), at:new Date() };
    addReq({ name:n, phone:m, device:WD.d.trim() || "–", repair:t("via_wd") + ": " + r, total:WD.x.trim(), via:"wd", contact:"E-Mail" });
    WD.open = false; WD.n = WD.m = WD.r = WD.d = WD.x = "";
    renderLegal(); const box = $("wd"); if (box) { box.focus({ preventScroll:true }); box.scrollIntoView({ block:"center" }); }
  });
}

/* ---------- Cookie consent (§ 25 TDDDG, DSK guidance: reject as easy as accept, on the first layer) ---------- */
const CONSENT_V = 1, CC_CATS = ["necessary", "stats", "marketing"], CC_MAX_AGE = 365 * 864e5;
let consent = LS.get("tt-consent", null);
if (consent && (consent.v !== CONSENT_V || !(Date.now() - Date.parse(consent.ts) < CC_MAX_AGE))) consent = null;
// Live site: each optional category registers its script loader here. Nothing in it runs before consent.
const CC_LOADERS = { stats:[], marketing:[] };
const ccLoaded = {};
const ccId = () => { try { return crypto.randomUUID().slice(0, 8); } catch (e) { return Math.random().toString(36).slice(2, 10); } };
function ccClear(k) {
  const re = k === "stats" ? /^_pk_/ : /^(_gcl_|_fbp|_ga)/;
  const host = location.hostname.replace(/^www\./, "");
  document.cookie.split(";").map(c => c.split("=")[0].trim()).filter(n => re.test(n)).forEach(n => {
    document.cookie = n + "=; Max-Age=0; path=/";
    if (host) document.cookie = n + "=; Max-Age=0; path=/; domain=." + host;
  });
}
function ccApply() {
  ["stats", "marketing"].forEach(k => {
    if (consent && consent[k]) { if (!ccLoaded[k]) { ccLoaded[k] = 1; CC_LOADERS[k].forEach(f => { try { f(); } catch (e) {} }); } }
    else ccClear(k);
  });
  document.documentElement.dataset.consent = consent ? CC_CATS.filter(k => consent[k]).join(" ") : "none";
}
function ccSave(sel) {
  consent = { v:CONSENT_V, ts:new Date().toISOString(), id:(consent && consent.id) || ccId(), necessary:true, stats:!!sel.stats, marketing:!!sel.marketing };
  LS.set("tt-consent", consent);
  // Live site: POST /api/consent { id, v, ts, choices } so the admin consent log holds proof of the choice.
  ccApply(); closeCCM(); renderCC(); toast(t("cc_saved"));
  if (!$("v-legal").hidden && legalKey === "cookies") renderLegal();
}
function ccPad() { const el = $("cc"); document.documentElement.style.setProperty("--cc-h", (el.hidden ? 0 : el.offsetHeight) + "px"); }
function renderCC() {
  const show = !consent && $("v-admin").hidden;
  const el = $("cc");
  el.innerHTML = `<div class="cc-in"><div class="cc-tx"><h2 id="ccH">${esc(t("cc_h"))}</h2><p>${esc(t("cc_p"))}</p>
    <p class="cc-l"><a href="#datenschutz">${esc(t("f_priv"))}</a><a href="#cookies">${esc(t("f_ck"))}</a><a href="#impressum">${esc(t("f_imp"))}</a></p></div>
    <div class="cc-act"><button type="button" class="ccb" data-cc="reject">${esc(t("cc_rej"))}</button><button type="button" class="ccb" data-cc="accept">${esc(t("cc_acc"))}</button><button type="button" class="cc-set" data-cc="settings">${esc(t("cc_set"))}</button></div></div>`;
  if (show && el.hidden && !el.dataset.seen) { el.dataset.seen = "1"; el.classList.add("intro"); setTimeout(() => el.classList.remove("intro"), 1600); }
  el.hidden = !show;
  document.documentElement.classList.toggle("cc-open", show);
  requestAnimationFrame(ccPad);
  if (!$("ccm").hidden) renderCCM();
}
function ccBox() {
  const c = consent;
  const row = k => { const on = k === "necessary" || (c && c[k]); return `<li><span>${esc(t("cc_cat")[k][0])}</span><b class="${on ? "on" : "off"}">${esc(k === "necessary" ? t("cc_always") : on ? t("cc_on") : t("cc_off"))}</b></li>`; };
  return `<div class="ccbox"><h2>${esc(t("cc_state"))}</h2>${c ? `<ul>${CC_CATS.map(row).join("")}</ul><p class="lg-meta">${esc(t("cc_when", { d:dtFmt(new Date(c.ts), { dateStyle:"medium", timeStyle:"short" }) }))}. ${esc(t("cc_id"))}: <code>${esc(c.id)}</code></p>` : `<p>${esc(t("cc_none"))}</p>`}<button type="button" class="btn" data-ccopen>${esc(t("cc_change"))}</button></div>`;
}
let CCM_SEL = { stats:false, marketing:false }, ccmReturn = null;
function renderCCM() {
  const cat = k => {
    const c = t("cc_cat")[k], list = COOKIES[lang][k], nec = k === "necessary";
    return `<div class="ccat"><div class="ccat-h"><label for="cc_${k}"><b>${esc(c[0])}</b><small>${esc(c[1])}</small></label>${nec ? `<span class="always">${esc(t("cc_always"))}</span>` : ""}<input type="checkbox" role="switch" class="sw" id="cc_${k}"${nec ? " checked disabled" : ` data-cck="${k}"${CCM_SEL[k] ? " checked" : ""}`}></div>
      <details><summary>${esc(t("cc_show", { n:list.length }))}</summary><ul class="cclist">${list.map(r => `<li><code>${esc(r[0])}</code><span>${esc(r[1])}</span><span>${esc(r[2])}</span><span>${esc(r[3])}</span></li>`).join("")}</ul></details></div>`;
  };
  $("ccmP").innerHTML = `<div class="ccm-top"><h2 id="ccmH">${esc(t("cc_title"))}</h2><button type="button" class="icb" data-ccx aria-label="${esc(t("close"))}">${ic("x", 2)}</button></div>
    <p class="ccm-intro">${esc(t("cc_intro"))}</p>${CC_CATS.map(cat).join("")}
    <p class="cc-l"><a href="#datenschutz">${esc(t("f_priv"))}</a><a href="#cookies">${esc(t("f_ck"))}</a><a href="#impressum">${esc(t("f_imp"))}</a></p>
    <div class="ccm-act"><button type="button" class="ccb" data-cc="reject">${esc(t("cc_rej"))}</button><button type="button" class="ccb alt" data-cc="save">${esc(t("cc_save"))}</button><button type="button" class="ccb" data-cc="accept">${esc(t("cc_acc"))}</button></div>`;
}
function lockScroll() { document.documentElement.style.overflow = (!$("bld").hidden || !$("ccm").hidden || !$("micm").hidden) ? "hidden" : ""; }
function openCCM() {
  CCM_SEL = { stats:!!(consent && consent.stats), marketing:!!(consent && consent.marketing) };
  ccmReturn = document.activeElement;
  renderCCM(); $("ccm").hidden = false; lockScroll(); $("ccmP").focus({ preventScroll:true });
}
function closeCCM() {
  if ($("ccm").hidden) return;
  $("ccm").hidden = true; lockScroll();
  if (ccmReturn && ccmReturn.isConnected && ccmReturn.focus) ccmReturn.focus({ preventScroll:true });
}
document.addEventListener("click", e => {
  const b = e.target.closest("[data-cc]");
  if (b) {
    const a = b.dataset.cc;
    if (a === "accept") ccSave({ stats:true, marketing:true });
    else if (a === "reject") ccSave({ stats:false, marketing:false });
    else if (a === "save") ccSave(CCM_SEL);
    else if (a === "settings") openCCM();
    return;
  }
  if (e.target.closest("[data-ccx]")) return closeCCM();
  if (e.target.closest("[data-ccopen]")) return openCCM();
  if (e.target.closest("[data-micx]")) return closeMic();
  if (e.target.closest("[data-mic-ok]")) { const go = micPending; micPending = null; closeMic(true); if (go) go(); }
});
$("ccm").addEventListener("change", e => { const k = e.target.dataset && e.target.dataset.cck; if (k) CCM_SEL[k] = e.target.checked; });
addEventListener("keydown", e => {
  if (e.key !== "Escape") return;
  if (!$("micm").hidden) closeMic(); else if (!$("ccm").hidden) closeCCM();
});
addEventListener("resize", () => { if (!$("cc").hidden) ccPad(); });

/* ---------- Voice input notice: shown once before the browser's speech recognition is used ---------- */
let micPending = null, micReturn = null;
function voiceGate(btn, onText, say) {
  if (LS.get("tt-mic-ok", false)) return startVoice(btn, onText, say);
  micPending = () => { LS.set("tt-mic-ok", true); startVoice(btn, onText, say); };
  micReturn = btn;
  $("micP").innerHTML = `<div class="ccm-top"><h2 id="micH">${ic("mic")}<span>${esc(t("mic_h"))}</span></h2><button type="button" class="icb" data-micx aria-label="${esc(t("close"))}">${ic("x", 2)}</button></div>
    <p class="ccm-intro">${esc(t("mic_p"))}</p><p class="fine"><a href="#datenschutz">${esc(t("f_priv"))}</a></p>
    <div class="ccm-act two-b"><button type="button" class="ccb alt" data-micx>${esc(t("mic_no"))}</button><button type="button" class="ccb" data-mic-ok>${esc(t("mic_ok"))}</button></div>`;
  $("micm").hidden = false; lockScroll(); $("micP").focus({ preventScroll:true });
}
function closeMic(keep) {
  if ($("micm").hidden) return;
  $("micm").hidden = true; lockScroll();
  if (!keep) micPending = null;
  if (micReturn && micReturn.focus) micReturn.focus({ preventScroll:true });
}
